<script setup lang="ts">
import PhotoField from './PhotoField.vue';
import PhotoGrid from './PhotoGrid.vue';
import { ref, watch } from 'vue';
import ForumAudio from './ForumAudio.vue';
import ForumAudioField from './ForumAudioField.vue';
import { api } from '../api';
import { type Row, forumCategories, statusNames, formatTime } from '../../shared/domain';
import { useForum } from '../../shared/useForum';
const props = defineProps<{ user: Row | null; manage?: boolean }>();const emit = defineEmits<{ (event: 'join'): void }>();
const { managed,managedReplies,restrictions,blocks,selected,replies,tab,category,query,error,message,busy,creating,form,reply,replyAudio,replyPhotos,quoted,operation,note,moderator,visible,detail,create,post,respond,ask,perform } = useForum(() => props.user,api);
watch(() => props.manage, value => { if (value) tab.value = 'manage'; }, { immediate: true });
const audioUploading = ref(false), photosPending = ref(false);
watch(() => [creating.value, selected.value?.id, props.user?.id], () => { audioUploading.value = false;photosPending.value = false; });
function newTopic(source?: Row) { if (props.user?.status !== 'approved') emit('join');else create(source); }
</script>
<template><section class="forum-hub"><div v-if="!creating && !selected" class="forum-heading"><div><p class="eyebrow">STORIES FROM OUR NEIGHBORS</p><h1>聊乡音，话家常。</h1><p>每一层回应，让老乡之间多一点了解。</p></div><button class="primary" @click="newTopic()">＋ 发起话题</button></div><p v-if="error && !operation" class="form-error" role="alert">{{ error }}</p><p v-if="message" class="status-note" role="status">{{ message }}</p>
<form v-if="creating" class="panel forum-form" @submit.prevent="post"><button type="button" class="text-button" @click="creating = false">← 返回论坛</button><h3>{{ form.forwardedTopicId ? '转发并说说你的看法' : '发起一个话题' }}</h3><label>标题<input v-model="form.title" required minlength="2" maxlength="80"></label><label>板块<select v-model="form.category"><option v-for="item in forumCategories" :key="item">{{ item }}</option></select></label><label>话题正文<textarea v-model="form.content" :required="!form.audio && !form.photos?.length" :minlength="form.audio || form.photos?.length ? 0 : 10" maxlength="5000" rows="8"></textarea></label><PhotoField v-model="form.photos" :user-id="user?.id" :disabled="busy" @busy="photosPending = $event"/><ForumAudioField v-model="form.audio" :user-id="user?.id" @busy="audioUploading = $event"/><p class="form-tip">主题和回复经审核后展示。转发保留原帖来源，原帖隐藏或删除后不再展示原文。</p><button class="primary" :disabled="busy || audioUploading || photosPending">提交审核</button></form>
<template v-else-if="selected"><button class="text-button" @click="selected = null">← 返回话题列表</button><article class="panel topic-detail"><span class="tag">{{ selected.category }} · {{ statusNames[selected.status] }}</span><h1>{{ selected.title }}</h1><p class="meta">楼主 · {{ selected.authorName }} · {{ formatTime(selected.createdAt) }}</p><p class="prose">{{ selected.content }}</p><PhotoGrid :photos="selected.photos || []"/><ForumAudio v-if="selected.audio" :attachment="selected.audio"/><div v-if="selected.forwarded" class="quoted-post"><p v-if="selected.forwarded.unavailable">原帖已不可见</p><template v-else><small>转发自 {{ selected.forwarded.authorName }}</small><h4>{{ selected.forwarded.title }}</h4><p>{{ selected.forwarded.content }}</p><PhotoGrid :photos="selected.forwarded.photos || []"/><ForumAudio v-if="selected.forwarded.audio" :attachment="selected.forwarded.audio"/><button class="text-button" @click="detail(selected.forwarded)">查看原帖 →</button></template></div><div class="button-row"><button v-if="selected.status === 'approved'" class="outline small" @click="newTopic(selected)">转发话题</button><button v-if="user?.status === 'approved' && selected.authorId !== user.id" class="text-button" @click="ask(selected,'block')">拉黑作者</button><button v-if="!selected.locked && (selected.authorId === user?.id || selected.canModerate)" class="text-button" @click="ask(selected,'lock')">关闭回复</button><button v-if="selected.authorId === user?.id || selected.canModerate" class="text-button" @click="ask(selected,'delete')">删除话题</button><template v-if="selected.canModerate"><button v-if="selected.status === 'approved'" class="text-button" @click="ask(selected,'hidden')">隐藏话题</button><button class="text-button" @click="ask(selected,'mute')">禁言作者</button><button class="text-button" @click="ask(selected,'kick')">移出版块</button></template></div></article>
<h3 class="reply-title">老乡的回复 · {{ replies.length }} 层可见</h3><div v-if="!replies.length" class="empty">还没有回复，来聊几句吧。</div><article v-for="(row,index) in replies" :key="row.id" class="panel floor"><div class="floor-head"><b>{{ row.authorName }}</b><span>{{ row.floor || index + 1 }} 楼 · {{ statusNames[row.status] }}</span></div><div v-if="row.quoted" class="quoted-post"><span v-if="row.quoted.unavailable">引用内容已不可见</span><template v-else>{{ row.quoted.floor }}楼 · {{ row.quoted.authorName }}<p>{{ row.quoted.content }}</p><PhotoGrid :photos="row.quoted.photos || []"/><ForumAudio v-if="row.quoted.audio" :attachment="row.quoted.audio"/></template></div><p class="prose">{{ row.status === 'deleted' ? '此层回复已删除' : row.content }}</p><PhotoGrid :photos="row.photos || []"/><ForumAudio v-if="row.audio && row.status !== 'deleted'" :attachment="row.audio"/><div class="button-row"><button v-if="row.status === 'approved' && !selected.locked" class="text-button" @click="quoted = row">引用回复</button><button v-if="row.status !== 'deleted' && (row.authorId === user?.id || row.canModerate)" class="text-button" @click="ask(row,'delete','replies')">删除回复</button><button v-if="row.canModerate && row.status === 'approved'" class="text-button" @click="ask(row,'hidden','replies')">隐藏回复</button><button v-if="user?.status === 'approved' && row.authorId !== user.id" class="text-button" @click="ask(row,'block')">拉黑</button><button v-if="row.canModerate" class="text-button" @click="ask(row,'mute')">禁言</button></div></article><form v-if="selected.status === 'approved' && !selected.locked" class="panel" @submit.prevent="user?.status === 'approved' ? respond() : emit('join')"><p v-if="quoted" class="quoted-post">回复 {{ quoted.floor }} 楼 · {{ quoted.authorName }} <button type="button" @click="quoted = null">取消引用 ×</button></p><label>发表回复<textarea v-model="reply" :required="!replyAudio && !replyPhotos.length" :minlength="replyAudio || replyPhotos.length ? 0 : 2" maxlength="2000" rows="4"></textarea></label><PhotoField :key="selected.id + replies.length" v-model="replyPhotos" :user-id="user?.id" :disabled="busy" @busy="photosPending = $event"/><ForumAudioField :key="selected.id" v-model="replyAudio" :user-id="user?.id" @busy="audioUploading = $event"/><button class="primary" :disabled="busy || audioUploading || photosPending">提交回复</button></form><p v-else class="status-note">话题暂不接受新回复</p></template>
<template v-else><div class="chips forum-tabs"><button :class="{ selected: tab === 'public' }" @click="tab = 'public'">全部话题</button><button v-if="user" :class="{ selected: tab === 'mine' }" @click="tab = 'mine'">我的发布</button><button v-if="moderator" :class="{ selected: tab === 'manage' }" @click="tab = 'manage'">版主管理</button><button v-if="moderator" :class="{ selected: tab === 'restrictions' }" @click="tab = 'restrictions'">板块限制</button><button v-if="user" :class="{ selected: tab === 'blocks' }" @click="tab = 'blocks'">我的黑名单</button></div>
<template v-if="['public','mine'].includes(tab)"><div class="filterbar"><div class="chips"><button v-for="item in ['全部', ...forumCategories]" :key="item" :class="{ selected: category === item }" @click="category = item">{{ item }}</button></div><input v-model="query" aria-label="搜索话题" placeholder="搜索话题、内容、老乡"></div><div v-if="!visible.length" class="empty">有故事，一起聊。发起第一个话题吧。</div><article v-for="row in visible" :key="row.id" class="panel topic-row"><div><span class="tag">{{ row.category }}</span><span class="meta">{{ row.authorName }} · {{ formatTime(row.createdAt) }}</span></div><h3><button :disabled="row.status === 'deleted'" @click="detail(row)">{{ row.title }}</button></h3><p>{{ row.content || (row.photos?.length ? row.photos.length + ' 张照片 · 点击查看' : row.audio ? '语音话题 · 点击收听' : '') }}</p><div class="floor-head"><small>{{ row.replyCount }} 条回复 · {{ row.locked ? '已关闭回复' : statusNames[row.status] }}</small><button v-if="row.status !== 'deleted'" class="text-button" @click="detail(row)">参与讨论 →</button></div></article></template>
<template v-if="tab === 'manage'"><p class="form-tip">版主只可管理被分配的板块。删除会清空正文；隐藏可恢复。</p><template v-for="section in [{ title: '话题管理', rows: managed, kind: 'topics' }, { title: '回复管理', rows: managedReplies, kind: 'replies' }]" :key="section.kind"><h3 class="reply-title">{{ section.title }}</h3><div v-if="!section.rows.length" class="empty">暂无内容</div><article v-for="row in section.rows" :key="row.id" class="panel moderation-row"><div><span class="tag">{{ row.category }} · {{ statusNames[row.status] }}</span><h4>{{ row.title || row.authorName + '的回复' }}</h4><p class="prose">{{ row.content }}</p><PhotoGrid :photos="row.photos || []"/><ForumAudio v-if="row.audio" :attachment="row.audio"/></div><div class="button-row"><button v-if="row.status === 'pending' || row.status === 'hidden'" class="primary small" @click="ask(row,'approved',section.kind)">{{ row.status === 'hidden' ? '恢复展示' : '审核通过' }}</button><button v-if="row.status === 'pending'" class="outline small" @click="ask(row,'rejected',section.kind)">退回</button><button v-if="row.status === 'approved'" class="outline small" @click="ask(row,'hidden',section.kind)">隐藏</button><button v-if="row.status !== 'deleted'" class="text-button" @click="ask(row,'delete',section.kind)">删除</button><button class="text-button" @click="ask(row,'mute')">禁言作者</button><button class="text-button" @click="ask(row,'kick')">移出版块</button></div></article></template></template>
<template v-if="tab === 'restrictions'"><p class="form-tip">禁言禁止在指定板块发帖和回复；移出同时限制账号进入该板块。公开内容仍可由访客浏览。</p><div v-if="!restrictions.length" class="empty">暂无板块限制</div><article v-for="row in restrictions" :key="row.id" class="panel"><h3>{{ row.name }} · {{ row.board }}</h3><p>{{ row.action === 'kick' ? '已移出版块' : '已禁言' }} · {{ row.reason }}</p><button class="outline small" @click="ask(row,'restore')">恢复参与</button></article></template>
<template v-if="tab === 'blocks'"><p class="form-tip">拉黑后隐藏对方的论坛内容，并禁止新的私聊和联系方式交换请求；已保存的信息无法收回。</p><div v-if="!blocks.length" class="empty">黑名单为空</div><article v-for="row in blocks" :key="row.id" class="panel floor-head"><b>{{ row.name }}</b><button class="outline small" @click="ask(row,'unblock')">取消拉黑</button></article></template></template>
<div v-if="operation" class="forum-overlay"><form class="panel" @submit.prevent="perform"><h3>{{ operation.title }}</h3><p>{{ operation.row.title || operation.row.authorName || operation.row.name }}</p><p v-if="operation.action === 'delete'" class="form-tip">确认后正文将清空，楼层与必要处理记录保留。</p><label v-if="!['approved','block','unblock','lock'].includes(operation.action)">处理说明<textarea v-model="note" required minlength="2" maxlength="300"></textarea></label><p v-if="error" class="form-error" role="alert">{{ error }}</p><div class="button-row"><button class="primary" :disabled="busy">确认操作</button><button type="button" class="outline" :disabled="busy" @click="operation = null">返回</button></div></form></div></section></template>
<style scoped>.forum-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:16px 0 28px}.forum-heading :is(h1,h2){font-size:28px;margin:12px 0}.forum-heading p{font-size:13px;color:#7e8987}.forum-tabs{margin:25px 0}.topic-row h3{font-size:21px;margin:18px 0}.topic-row h3 button{text-align:left}.topic-row>p{color:#7e8987;font-size:14px;line-height:1.9;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.topic-row .meta{margin-left:18px}.floor-head{display:flex;justify-content:space-between;align-items:center;gap:20px}.floor-head span,.floor-head small{font-size:12px;color:#8a8f7d}.floor .prose{margin:20px 0}.reply-title{font-size:21px;margin:28px 0 18px}.quoted-post{background:#eee8d9;border-left:3px solid #c3a466;border-radius:6px;padding:18px;color:#7b745e;margin:18px 0;font-size:13px;line-height:1.9;overflow-wrap:anywhere}.quoted-post h4{font-size:16px;margin:10px 0}.quoted-post p{white-space:pre-wrap}.topic-detail :is(h1,h2){font-size:28px;margin:20px 0}.topic-detail .prose{white-space:pre-wrap;margin:20px 0}.forum-form{max-width:800px}.forum-form h3{font-size:23px;margin:20px 0}.forum-overlay{position:fixed;inset:0;background:#1c35488c;z-index:200;display:grid;place-items:center;padding:20px}.forum-overlay .panel{width:100%;max-width:540px;max-height:85vh;overflow:auto}.forum-overlay h3{font-size:22px;margin-bottom:18px}.moderation-row h4{margin:15px 0}.moderation-row .prose{max-height:180px;overflow:auto}@media(max-width:600px){.forum-heading{align-items:flex-start;flex-direction:column}.forum-heading :is(h1,h2),.topic-detail :is(h1,h2){font-size:24px}.topic-row .meta{display:block;margin-left:0}.floor-head{gap:10px}.forum-tabs{gap:8px}}</style>
